#define GSOk 0
#define GSErrorOther -2
#define SCE_RDONLY 1

extern "C" int sceMcOpen(int port, int slot, const char *name, int mode);
extern "C" int sceMcSync(int mode, int *cmd, int *result);
extern "C" int sceMcRead(int fd, void *data, int size);
extern "C" int sceMcClose(int fd);

class GenericGameSaver
{
public:
  static int getInfo(int port, int slot, int *type, int *free, int *formatted);
  static int readData(int port, int slot, char *name, void *data, int maxSize);
};

int GenericGameSaver::readData(int port, int slot,
                               char *name,
                               void *data, int maxSize)
{
  int fp, type, free, formatted, cmd, result;
  int infoRes = getInfo(port, slot, &type, &free, &formatted);
  int bytes =0;
  if (infoRes != GSOk)
    return infoRes;

  if (sceMcOpen(port, slot, name, SCE_RDONLY) != 0)
    if (sceMcOpen(port, slot, name, SCE_RDONLY) != 0)
      return GSErrorOther;

  if (sceMcSync(0, &cmd, &result) != 1)
  {
    if (sceMcOpen(port, slot, name, SCE_RDONLY) != 0)
    {
      if (sceMcOpen(port, slot, name, SCE_RDONLY) != 0)
      {
        return GSErrorOther;
      }
      else
      {
        if (sceMcSync(0, &cmd, &result) != 1)
          return GSErrorOther;
      }
    }
    else
    {
      if (sceMcSync(0, &cmd, &result) != 1)
        return GSErrorOther;
    }
  }

  if (result < 0)
    return GSErrorOther;

  fp = result;

  if (sceMcRead(fp, data, maxSize) != 0)
    if (sceMcRead(fp, data, maxSize) != 0)
      return GSErrorOther;

  while (sceMcSync(1, &cmd, &result)==0)
  {
    if (result < 0) 
    {
      sceMcClose(fp);
      sceMcSync(0, &cmd, &result);
      return GSErrorOther;
    }
    bytes +=result;
  }
  if (result < 0) 
  {
    sceMcClose(fp);
    sceMcSync(0, &cmd, &result);
    return GSErrorOther;
  }
  bytes +=result;
  if (sceMcClose(fp) != 0)
    if (sceMcClose(fp) != 0)
      return GSErrorOther;

  sceMcSync(0, &cmd, &result);


  return GSOk;
}
